 async function signOut(){await supabase.auth.signOut();setScreen("home");setWorld(null);setNotice("Déconnecté.");}
 async function createWorld(){if(!session){setAuthOpen(true);return}if(!worldName.trim()){setNotice("Donne un nom à ton monde.");return}if(!fiction&&fictionalCreatures){setNotice("Les créatures fictives nécessitent l'autorisation de la fiction.");return}setBusy(true);const {data:{user}}=await supabase.auth.getUser();const {data,error}=await supabase.from("worlds").insert({owner_id:user?.id,name:worldName.trim(),description:"Monde créé avec Arthenis.",theme,magic_enabled:magic,fiction_enabled:fiction,fictional_creatures_enabled:fictionalCreatures,is_public:isPublic,visual_bible:{theme,magic,fiction,fictionalCreatures},world_memory:{day:1,map_version:0}}).select().single();setBusy(false);if(error){setNotice(error.message);return}if(data){await loadWorlds();await selectWorld(data as World)}setNotice("✦ Monde créé.");}
